# Formats all hand-written headers under shared/ using clang-format.
#
# Excludes shared/utfcpp (a vendored third-party submodule we don't own the
# style of) and shared/bindings.h (generated by cbindgen on every `cargo
# build`, so any manual formatting there is immediately overwritten anyway).

$utfcppPrefix = Join-Path "shared" "utfcpp"

$headers = Get-ChildItem -Path shared -Recurse -Include *.h, *.hpp |
    Where-Object {
        -not $_.FullName.Contains($utfcppPrefix) -and
        $_.Name -ne "bindings.h"
    }

if (-not $headers) {
    Write-Host "No headers found to format."
    exit 0
}

foreach ($header in $headers) {
    Write-Host "Formatting $($header.FullName)"
    clang-format -i $header.FullName
}
